CY.i18n.cards("fr", {
  arrive: "{n} franchit la porte d'entrée et demanda à rester quelques jours.",
  ok: "Avant de partir, {n} laissa un souvenir : {s}. Et dit : « {q} »",
  miss: "{n} remercia et repassa la porte."
}, {
  nightingale: ["Florence Nightingale", "XIXe siècle, Royaume-Uni", "Une lampe à huile", "", "Elle se frotta les yeux : « Cela fait longtemps que je n'ai pas dormi toute une nuit. »", "Elle regarda ta famille : « Ceux qui prennent soin des autres ont aussi besoin qu'on prenne soin d'eux. »", "Elle dormit des heures et se réveilla bien mieux.",
    { arrive: "Florence Nightingale franchit la porte d'entrée et demanda à emprunter un lit, ayant soigné trop de monde.", ok: "Avant de partir, Florence Nightingale dit que tu prends bien soin de ta famille et te demanda de continuer. Elle laissa une lampe à huile.", miss: "Florence Nightingale remercia doucement et repassa la porte." }],
  zhuge: ["Zhuge Liang", "Trois Royaumes, Shu Han", "Un éventail de plumes", "", "Il fit un geste de la main : « Tant d'affaires, grandes et petites, et je ne dors jamais bien. »", "Il sourit : « Quelqu'un a dit un jour que je mange peu et que je fais trop. Il n'avait pas tort. »", "Il dormit jusqu'au crépuscule et se réveilla bien reposé.",
    { arrive: "Zhuge Liang franchit la porte d'entrée, les yeux cernés, et demanda s'il pouvait emprunter un lit.", ok: "Avant de partir, Zhuge Liang dit que la famille passe avant tout et te supplia de ne pas t'épuiser. Il laissa un éventail de plumes.", miss: "Zhuge Liang s'inclina pour remercier et repassa la porte." }],
  curie: ["Marie Curie", "XIXe et XXe siècles, Pologne et France", "Une copie d'une page de carnet", "", "Elle cacha ses mains derrière son dos : « Mes doigts me font parfois mal, sans doute à cause du laboratoire. »", "Elle regarda ta lampe avec curiosité : « Y a-t-il quelque chose qui puisse arrêter ces rayons invisibles ? »", "Elle l'enfila et hocha gravement la tête.",
    { arrive: "Marie Curie franchit la porte d'entrée et dit qu'elle n'était pas sortie du laboratoire depuis une éternité et qu'elle aimerait rester quelques jours.", ok: "Avant de partir, Marie Curie te laissa la copie d'une page de carnet : « Merci d'avoir pensé à cela pour moi. »", miss: "Marie Curie, inquiète pour ses expériences, dit un au revoir rapide et repartit.", late: "En sortant, elle dit doucement : « Ton attention me touche, mais j'avais surtout besoin de quoi protéger mes mains. »" }],
  galois: ["Évariste Galois", "XIXe siècle, France", "Une feuille couverte de formules", "Merci d'avoir remarqué que je manquais de temps.", "Il écrivait sans cesse, et dans la marge se trouvait une ligne : « Je n'ai pas le temps. »", "Il dit qu'il devait tout écrire cette nuit, au cas où demain serait trop tard.", "Il le prit et se pencha aussitôt sur le bureau pour écrire."],
  mozart: ["Wolfgang Amadeus Mozart", "XVIIIe siècle, Autriche", "Une copie d'une page de musique", "La musique est pour ceux qui écoutent. Merci d'avoir écouté.", "Il fredonna un air et dit qu'il irait dans un nouvel opéra.", "Il demanda s'il y avait dans la maison quelque chose dans quoi on puisse souffler, ne serait-ce qu'un seul objet.", "Il essaya deux notes et ses yeux s'illuminèrent."],
  beethoven: ["Ludwig van Beethoven", "XVIIIe et XIXe siècles, Allemagne", "Une copie d'une page d'un cahier de conversation", "Quand quelqu'un prend la peine de m'écrire, je ne suis pas seul.", "Il montra ses oreilles, fit un geste de la main et te fit signe d'écrire ce que tu voulais dire.", "Il portait partout un petit carnet très usé.", "Il ouvrit le nouveau carnet et hocha la tête."],
  da_vinci: ["Léonard de Vinci", "XVe et XVIe siècles, Italie", "Une copie d'une page de manuscrit", "La curiosité est le plus beau cadeau. Merci d'avoir regardé les oiseaux avec moi.", "Il écrivait de droite à gauche, en miroir, de sorte qu'il fallait un miroir pour le lire.", "Il regarda longtemps les oiseaux, se demandant comment ils se reposent sur le vent.", "Il le prit et se mit aussitôt à dessiner."],
  li_bai: ["Li Bai", "Dynastie Tang, Chine", "Une copie d'une page de poèmes", "Tant que la lune est là, quelqu'un te tient compagnie.", "Il fixait la lune derrière la fenêtre en murmurant pour lui-même.", "Il demanda du papier et un pinceau, car un poème doit s'écrire tant qu'il est frais, et se demanda ce qui se trouvait au loin.", "Il prit le pinceau et écrivit, et la lune était déjà levée avant que l'encre soit sèche."],
  du_fu: ["Du Fu", "Dynastie Tang, Chine", "Une copie d'une page de poèmes", "C'est la chaleur qui donne sa force à un poème.", "Il resserra sa robe légère et dit que cet hiver était particulièrement froid.", "En regardant la lumière de ta lampe, il dit que ce serait merveilleux si chacun avait un endroit chaud où vivre.", "Tenant quelque chose de chaud, il poussa un long soupir."],
  su_shi: ["Su Shi", "Dynastie Song, Chine", "Une page de recette et de vers", "La façon dont la journée se passe dépend de ce seul repas.", "Il huma l'air et demanda ce qui mijotait à la cuisine, disant avoir un jour inventé lui-même un braisé.", "Il dit que les poèmes pouvaient attendre, mais pas le dîner.", "Il but une gorgée et plissa les yeux de contentement."],
  zhang_heng: ["Zhang Heng", "Dynastie des Han orientaux, Chine", "Une copie d'une carte du ciel", "Le ciel se mesure peu à peu.", "Il renversa la tête vers le ciel nocturne et dit qu'il voulait consigner les étoiles une à une.", "Il étudia longtemps ta pendule et demanda comment elle pouvait donner si bien l'heure.", "Il la régla encore et encore, en souriant."],
  li_shizhen: ["Li Shizhen", "Dynastie Ming, Chine", "Un spécimen d'herbe pressée", "Chaque plante a son usage. Ne les méprise jamais.", "Il s'accroupit près d'un pot de fleurs, étudiant de près les nervures d'une feuille.", "Il dit qu'il voulait connaître toutes les herbes médicinales sous le soleil et les consigner une à une.", "Il le rangea et se raccroupit de nouveau près du pot de fleurs."],
  lin_daiyu: ["Lin Daiyu", "Un personnage du « Rêve dans le pavillon rouge »", "Une fleur de soie", "C'est une chance que quelqu'un se souvienne de toi.", "Elle toussa doucement et dit que le vent de la nuit était un peu froid.", "Un livre à la main, elle demanda si tu avais quelque chose qui puisse faire du bien à quelqu'un.", "Elle le prit et dit un doux merci."],
  archimedes: ["Archimède", "Grèce antique", "Un petit levier", "Trouve le point d'appui et le reste n'est qu'une question de temps.", "Il fixa longtemps ta baignoire, perdu dans ses pensées.", "Il dit qu'avec un point d'appui assez ferme, il pourrait soulever le monde entier.", "Il le retourna en souriant comme un enfant."],
  ibn_sina: ["Ibn Sina (Avicenne)", "XIe siècle, Perse", "Une copie d'une page de manuscrit", "Le devoir d'un médecin est de transmettre ce qu'il sait.", "Il feuilletait tes étagères en disant qu'un bon livre peut rassurer une personne mieux que n'importe quel remède.", "Il dit qu'il voulait consigner chaque maladie qu'il avait vue pour ceux qui viendraient après lui.", "Il l'examina soigneusement et hocha la tête."],
  al_khwarizmi: ["Al-Khwârizmî", "IXe siècle, Asie centrale", "Une copie d'une page de calculs", "Décompose un problème difficile et avance pas à pas.", "Il dessina une équation par terre et te la résolut pas à pas.", "Il demanda si ta carte était exacte, disant en avoir dessiné une lui-même.", "Il la déplia et se mit à calculer."],
  ada: ["Ada Lovelace", "XIXe siècle, Royaume-Uni", "Une copie d'une page de notes", "L'imagination et l'arithmétique sont en réalité la même chose.", "Elle dit que peut-être un jour les machines pourraient composer de la musique.", "Elle demanda une bonne plume, car ses notes n'étaient pas encore terminées.", "Elle prit la plume et ajouta aussitôt une ligne à ses notes."],
  ramanujan: ["Srinivasa Ramanujan", "Début du XXe siècle, Inde", "Une copie d'une page de notes", "Les nombres ont des sentiments, si tu leur tiens compagnie.", "Il feuilletait un vieux carnet en disant que certaines formules lui venaient en rêve.", "Il parla de la cuisine de son pays, une lueur dans les yeux.", "Il mangea lentement, puis rouvrit son carnet."],
  tagore: ["Rabindranath Tagore", "XIXe et XXe siècles, Inde", "Une copie d'une page de poèmes", "Ne te presse ni de grandir, ni de vieillir.", "Il regardait la pluie à la fenêtre et dit qu'il voulait écrire un court poème.", "Il dit qu'il ne s'était mis à la peinture que tard dans la vie, et qu'il l'aimait.", "Il le prit en contemplant la pluie dehors."],
  hokusai: ["Katsushika Hokusai", "Période d'Edo, Japon", "Une petite peinture d'une vague", "En peignant jusqu'au bout, on reste un élève.", "Il dit avoir peint toute sa vie et vouloir encore quelques années pour s'améliorer.", "Il regarda par ta fenêtre et dit qu'il voulait peindre une vague.", "Il étala le papier et rit en traçant le premier trait."],
  murasaki: ["Murasaki Shikibu", "Période de Heian, Japon", "Une copie d'une page du récit", "On écrit des histoires pour des gens qui ne sont pas encore nés.", "Elle s'assit tranquillement près de la fenêtre et dit qu'elle voulait écrire quelque chose ce soir.", "Elle regarda le ciel et demanda s'il pouvait être un peu plus clair.", "La lampe allumée, elle prit le pinceau et hocha doucement la tête."],
  basho: ["Matsuo Bashō", "Période d'Edo, Japon", "Une copie d'une page de haïkus", "Tout ce que tu rencontres sur la route est un poème.", "Il regarda ses sandales de paille et dit que la route était encore longue.", "Il dit que le meilleur d'un voyage, c'est une tasse de thé chaud.", "Il les essaya, fit deux pas et hocha la tête en souriant."],
  ibn_battuta: ["Ibn Battuta", "XIVe siècle, Maroc", "Une copie d'une page du livre de voyage", "Plus tu vas loin, mieux tu sais où est ta maison.", "Il parlait sans cesse des villes qu'il avait vues en chemin.", "Il demanda plusieurs fois où se trouvait exactement ta maison.", "Il la déplia et rit en pointant un endroit dessus."],
  austen: ["Jane Austen", "XVIIIe et XIXe siècles, Royaume-Uni", "Une copie d'une page de manuscrit", "Même une petite table peut porter le monde entier.", "Elle glissait son manuscrit sous un buvard dès que quelqu'un s'approchait.", "Elle dit qu'une tasse de thé chaud et une petite table suffisaient pour un chapitre.", "Elle sourit et le posa sur sa petite table."],
  pasteur: ["Louis Pasteur", "XIXe siècle, France", "Une copie d'une page de notes de laboratoire", "Ce qu'on voit est le résultat, ce qu'on ne voit pas est la cause.", "Il regarda longtemps une seule goutte d'eau en disant qu'il y avait un monde invisible à l'intérieur.", "Il dit qu'il voulait que tout ce que les gens mangent et boivent soit un peu plus propre.", "Il se pencha et observa en retenant son souffle."],
  seacole: ["Mary Seacole", "XIXe siècle, Jamaïque et Royaume-Uni", "Un petit sachet d'herbes", "Partout où quelqu'un a besoin de moi, c'est là ma place.", "Elle portait un sac d'herbes qu'elle avait mélangées elle-même et disait l'emporter partout.", "Elle disait que, devant quelqu'un qui se sentait mal, elle commençait toujours par un bol de soupe chaude.", "Elle hocha la tête et le rangea dans son propre sac."],
  dickinson: ["Emily Dickinson", "XIXe siècle, États-Unis", "Une copie d'une page de courts poèmes", "L'espoir est cette chose à plumes.", "Elle dit doucement que les vers courts, la nuit, lui convenaient le mieux.", "Elle demanda un petit carnet, juste assez grand pour un poème.", "Elle ouvrit le carnet avec délicatesse et sourit sans un mot."],
  wang_xizhi: ["Wang Xizhi", "Dynastie des Jin orientaux, Chine", "Une copie d'une page de calligraphie", "Que l'écriture soit belle dépend du calme de l'esprit.", "Il se rappela une réunion de printemps où chacun écrivait des poèmes au bord du ruisseau.", "Il demanda si ta table était assez grande pour une feuille de papier.", "Il étala le papier, respira profondément et posa le premier trait."],
  zhang_zhongjing: ["Zhang Zhongjing", "Dynastie des Han orientaux, Chine", "Une copie d'une page du livre de médecine", "Ce que tu as vu et noté est un remède pour ceux qui viendront après.", "Il dit vouloir réunir dans un livre les maladies qu'il avait vues pour épargner des peines à ceux qui suivront.", "Il huma ton thé et dit qu'il lui faudrait savoir de quelle sorte il s'agissait.", "Il le regarda attentivement et hocha la tête."],
  euler: ["Leonhard Euler", "XVIIIe siècle, Suisse", "Une copie d'une page de calculs", "Même quand la lumière baisse, tu peux continuer à calculer.", "Il plissa les yeux sur ton écriture et dit que sa vue baissait.", "Il dit qu'il pouvait continuer à calculer même avec un enfant grimpant sur ses genoux.", "Il les mit et rapprocha le papier."],
  hippocrates: ["Hippocrate", "Grèce antique", "Une feuille de saule", "Regarde un peu plus longtemps, attends un peu plus longtemps, et le corps s'aidera lui-même.", "Il resta longtemps assis près du lit sans un mot, observant attentivement avant de demander comment s'était passée la nuit.", "Il dit que, selon la tradition, il avait un jour fait mâcher de l'écorce de saule, et que l'alimentation simple et le repos comptent le plus.", "Il la mâcha, hocha la tête et dit que cela avait le goût de la maison."],
  ibn_al_nafis: ["Ibn al-Nafis", "XIIIe siècle, Syrie et Égypte", "Une copie d'une page de manuscrit sur les poumons et le sang", "Ce n'est qu'en regardant avec soin qu'on écrit avec soin.", "Il dessina un cœur sur le papier et dit que le sang ne traverse pas directement la cloison du milieu, mais fait un détour par les poumons.", "Il dit avoir passé la plus grande partie de sa vie dans les hôpitaux et aimer surtout voir les malades guérir peu à peu.", "Il le prit et l'ouvrit aussitôt pour écrire."],
  omar_khayyam: ["Omar Khayyam", "XIe et XIIe siècles, Perse", "Une page de calculs de calendrier", "Compte bien les jours et tu pourras bien les vivre.", "Il dessina quelques coniques et dit que même les équations du troisième degré pouvaient se résoudre par la géométrie.", "Il dit avoir passé toute la soirée sur des calculs de calendrier et vouloir quelqu'un pour une partie d'échecs.", "Il disposa les pièces une à une et dit que les étoiles seraient sûrement belles ce soir."],
  scheherazade: ["Shéhérazade", "Un personnage des « Mille et Une Nuits »", "Une bougie à histoires", "Raconte une histoire à quelqu'un qui veut l'écouter, et elle ne finit jamais.", "Elle dit qu'elle portait en elle tant d'histoires qu'une nuit ne suffirait jamais.", "Elle demanda si quelqu'un dans la maison voulait entendre une histoire, de préférence avant de dormir.", "Elle posa la lampe près du lit et commença doucement la première histoire."],
  sushruta: ["Sushruta", "Inde antique, auteur traditionnel d'un texte de chirurgie", "Une copie d'une page de dessins d'instruments", "Mains sûres, esprit calme, et pense-y une fois avant de commencer.", "Il dit qu'il faut s'exercer à la chirurgie d'abord sur des courges et des outres de cuir, jamais directement sur une personne.", "Il essuya chaque instrument et les rangea, disant que chaque geste doit être pensé avant que la main ne bouge.", "Il les enfila, les regarda et hocha la tête, satisfait."],
  aryabhata: ["Aryabhata", "Ve et VIe siècles, Inde", "Une page de calculs de pi", "Les nombres ne mentent pas, pourvu que tu acceptes de compter encore une fois.", "Il montra le ciel et dit que les étoiles semblent tourner, mais que c'est peut-être le sol sous nos pieds qui tourne.", "Il calcula que le rapport de la circonférence au diamètre vaut environ 3,1416, et le vérifia encore et encore.", "Il l'installa, regarda à travers et nota soigneusement quelques chiffres."],
  le_huu_trac: ["Lê Hữu Trác (Hải Thượng Lãn Ông)", "XVIIIe siècle, Viêt Nam", "Un fagot d'herbes séchées", "Le cœur d'un guérisseur compte plus que le remède.", "Il dit que les remèdes n'ont pas à être chers : une plante au bord d'un champ est aussi un remède, si on l'emploie bien.", "Il dit qu'il n'est pas nécessaire de faire payer les pauvres et que l'on peut cultiver soi-même les herbes.", "Il fit rouler les graines entre ses doigts et dit qu'une poignée semée maintenant suffirait l'an prochain."],
  raden_saleh: ["Raden Saleh", "XIXe siècle, Java", "Une copie d'un petit tableau", "Pour peindre la façon dont tombe la lumière, il faut continuer à la regarder.", "Il portait un carnet de croquis et pouvait rester assis toute l'après-midi dans la cour.", "Il aimait peindre les animaux et les changements de temps, et demanda si ton chat resterait immobile.", "Il ouvrit les couleurs et se mit à les mélanger face à la fenêtre."],
  sunthorn_phu: ["Sunthorn Phu", "XVIIIe et XIXe siècles, Thaïlande", "Une copie d'une page de vers", "La route est un livre qu'on ne finit jamais : on ne l'a parcourue que lorsqu'on l'a écrite.", "Il dit qu'il écrivait partout où il marchait et que n'importe quel paysage du chemin pouvait devenir un poème.", "Il aimait rimer, et une demi-phrase se changeait en vers.", "Il mit les chaussures, fit un tour de la pièce et murmura un nouveau vers."],
  al_fihri: ["Fatima al-Fihri", "IXe siècle, Maroc", "Un croquis d'une école", "Un lieu où les gens peuvent étudier est le plus bel héritage.", "Elle demanda ce que lisaient les enfants et dit qu'un lieu pour étudier compte plus que presque tout.", "Elle dit avoir employé ce que sa famille lui avait laissé à construire un lieu où l'on pût étudier.", "Elle posa la lampe sur la table et ouvrit un livre."],
  ibn_khaldun: ["Ibn Khaldoun", "XIVe siècle, Tunisie et Égypte", "Une copie d'une page de l'Introduction", "Tu vois loin parce que tu as vu clairement ce qui a précédé.", "Il dit que pour comprendre une chose, on ne peut se fier à la seule légende : il faut regarder les causes avant et après.", "Il portait une grosse pile de manuscrit et dit qu'elle devait encore être révisée.", "Il monta la lampe et retourna à son manuscrit."],
  horton: ["James Africanus Horton", "XIXe siècle, Sierra Leone", "Une page de relevés météo et de cas", "Les relevés sont honnêtes, pourvu qu'on les tienne.", "Il dit que les maladies d'un endroit doivent se lire avec son climat, son eau et son alimentation, et que tout doit être consigné.", "Il avait étudié la médecine en Grande-Bretagne et, de retour, continuait de consigner les cas de sa terre.", "Il l'ouvrit, regarda le ciel et dit que la saison des pluies demandait une colonne de plus."],
  anansi: ["Anansi", "Contes akan d'Afrique de l'Ouest", "Un court brin d'argent", "Les histoires se tissent, fil après fil, alors prends ton temps.", "Il dit que toutes les histoires lui avaient appartenu autrefois et n'avaient été emportées dans le monde que plus tard.", "Il occupait huit mains et les trouvait encore trop peu, et demanda si tu avais des gants en trop.", "Il les enfila et remua joyeusement les doigts."],
  imhotep: ["Imhotep", "Égypte antique, resté dans les mémoires comme guérisseur", "Un croquis d'un édifice à degrés", "Tout ce qui est haut commence en un lieu stable.", "Il dit que pour élever un haut édifice de pierre, il faut mesurer les fondations plus soigneusement que quiconque.", "Plus tard, on dit qu'il savait aussi guérir ; il sourit sans confirmer ni démentir.", "Il le déplia, montra un point et dit qu'on mesurerait à partir de là."],
  sor_juana: ["Sœur Juana Inés de la Cruz", "XVIIe siècle, Nouvelle-Espagne (Mexique actuel)", "Une copie d'une page de vers", "Un livre qu'on a envie de lire vaut la peine d'attendre.", "Son étagère contenait plus de livres que celle de n'importe qui, et elle dit qu'un mur entier ne suffisait pas.", "Elle dit que les femmes aussi ont le droit de lire, et le dit très calmement.", "Elle tint le livre, tourna à la première page et se mit à lire en silence."],
  machado: ["Machado de Assis", "XIXe et XXe siècles, Brésil", "Une copie d'une page d'épreuves", "Compose chaque mot comme il faut, et tu seras digne du lecteur.", "Il parlait posément et racontait toujours une blague juste quand on le croyait sur le point d'être sérieux.", "Il dit qu'un lecteur est comme un ami et qu'en écrivant, il faut le saluer de temps en temps.", "Il les mit, regarda autour de lui et sourit, satisfait."],
  finlay: ["Carlos Finlay", "XIXe et XXe siècles, Cuba", "Un croquis d'un moustique", "La patience marche mieux que la dispute.", "Il fixa longtemps un moustique et dit qu'une petite chose peut être la source d'un grand ennui.", "Il dit que peu importait qu'on se soit moqué de son idée pendant des années : on attend simplement les preuves.", "Il y colla un œil et ne leva pas la tête pendant longtemps."],
  kahlo: ["Frida Kahlo", "XXe siècle, Mexique", "Une fleur en papier", "Les couleurs ne mentent pas ; je ne peins que ce que je vois.", "Elle demanda si tu avais un miroir, car elle aimait se peindre en se regardant dans l'un d'eux.", "Ses vêtements étaient de couleurs vives, et elle dit avoir eu chez elle des singes, des chiens et un perroquet.", "Elle étala aussitôt les peintures et dit qu'elle commencerait par le rouge de l'écharpe."],
  sequoyah: ["Sequoyah", "XVIIIe et XIXe siècles, Cherokee", "Une copie d'une page d'un tableau de syllabes", "Ta propre langue mérite ses propres lettres.", "Il dit qu'il voulait créer un système d'écriture pour sa propre langue, qu'il avait essayé pendant des années en modifiant symbole après symbole.", "Il portait une pile de papier couverte de symboles et dit qu'il devait encore les vérifier une fois.", "Il approcha la lampe et vérifia les symboles un à un."],
  tupaia: ["Tupaia", "XVIIIe siècle, îles de la Société", "Une copie d'une carte marine", "En mer, il n'y a pas de routes, seulement des directions dont on se souvient.", "Il n'avait pas besoin de carte du ciel : à la direction où se lèvent les étoiles, il savait dire où se trouvait chaque île.", "Il dessina sur le papier une carte de la mer, avec plus de soixante-dix îles.", "Il la déplia et suivit du doigt les îles lointaines."]
});

CY.i18n.register("fr", { "title.uncle": "Tonton", "title.aunt": "Tata",
  "visit.fam.med.peer": "{guest} parla avec {who} des médicaments que chacun prend chaque jour, et ils se rappelèrent de les prendre à l'heure.", "visit.fam.sci.peer": "{guest} se tint à côté de {who} à la fenêtre, et tous deux se demandèrent s'il pleuvrait demain.", "visit.fam.art.peer": "{guest} récita un vieux vers à {who}, et tous deux hochèrent la tête.", "visit.fam.edu.peer": "{guest} parla avec {who} des vieux livres que chacun avait lus.", "visit.fam.pol.peer": "{guest} versa une tasse de thé à {who}, et les deux restèrent assis côte à côte sans dire grand-chose.", "visit.fam.trv.peer": "{guest} parla avec {who} du temps et de la cuisine de leurs pays." });
CY.i18n.said("fr", {
  nightingale: ["La toute première exigence d'un hôpital est de ne pas nuire aux malades."],
  zhuge: ["Sans simplicité, pas de clarté de dessein ; sans calme, pas d'horizon lointain."],
  curie: ["Rien dans la vie n'est à craindre, tout est à comprendre."],
  galois: ["Je n'ai pas le temps… Je n'ai pas le temps."],
  mozart: ["Je ne prête aucune attention aux louanges ni aux blâmes de personne. Je suis simplement mes propres sentiments."],
  beethoven: ["Tous les hommes deviendront frères."],
  da_vinci: ["Apprendre n'épuise jamais l'esprit."],
  li_bai: ["Le ciel m'a donné des talents, et ils doivent servir ; dépense mille pièces d'or, elles reviendront."],
  du_fu: ["Si seulement j'avais dix mille vastes maisons pour abriter tous les lettrés pauvres sous le ciel, tous souriants !"],
  su_shi: ["La vraie saveur de ce monde est une joie simple et tranquille."],
  zhang_heng: ["Le ciel est comme un œuf, et la terre est le jaune qu'il contient."],
  archimedes: ["Eurêka ! J'ai trouvé !"],
  ibn_sina: ["Pour vraiment connaître une chose, il faut en connaître les causes."],
  ada: ["L'imagination est la faculté de découvrir. Elle pénètre les mondes invisibles qui nous entourent."],
  tagore: ["Que ta vie danse légèrement au bord du Temps, comme la rosée au bout d'une feuille."],
  hokusai: ["À soixante-treize ans, j'ai appris un peu de la vraie structure des animaux, des plantes, des arbres, des oiseaux, des poissons et des insectes."],
  basho: ["Un vieil étang : une grenouille y saute, le bruit de l'eau."],
  austen: ["Rien ne vaut de rester chez soi pour un vrai confort."],
  pasteur: ["Dans le champ de l'observation, le hasard ne favorise que l'esprit préparé."],
  dickinson: ["Je ne suis personne ! Et toi, qui es-tu ?"],
  wang_xizhi: ["En levant les yeux, je vois combien l'univers est vaste ; en les baissant, combien les choses sont riches."],
  zhang_zhongjing: ["Cherche avec ardeur les enseignements anciens et rassemble largement toutes les recettes."],
  euler: ["Rien ne se produit dans le monde dont le sens ne soit celui d'un maximum ou d'un minimum."],
  hippocrates: ["La vie est brève, l'art est long."],
  scheherazade: ["Et ce n'était que le début de l'histoire."],
  sor_juana: ["Je n'étudie pas pour en savoir plus, mais pour en ignorer moins."],
  kahlo: ["Je peins ma propre réalité."]
});
CY.i18n.register("fr", { "corner.rate_tip": "Le chiffre précédé de + est le revenu du foyer par heure de jeu pendant le travail. Plus de confort rapporte plus." });

CY.i18n.asks("fr", {
  "archimedes": ["Donne-moi un point d'appui et je soulèverai la Terre. Me crois-tu ?", "Oui, mais donne-moi d'abord un levier assez long.", "Non. Discutons-en.", "Bien ! Dessine-moi ton levier et nous le calculerons pouce par pouce."],
  "nightingale": ["Tu es occupé depuis longtemps. Ceux qui prennent soin des autres doivent aussi dormir.", "D'accord, je me repose un moment.", "Après cette période chargée.", "Je garde la lampe pour toi. Va."],
  "zhuge": ["As-tu un plan pour la maison ? Laisse-moi en fixer l'ordre.", "Conseille-moi, je te prie.", "Je m'en occupe. Prends un thé.", "L'urgent d'abord, le lent ensuite, et surtout ne t'épuise pas."],
  "curie": ["Sais-tu ce que tu fais chaque jour ? Seul ce qu'on comprend cesse de faire peur.", "Je veux essayer de comprendre.", "Je veux juste en finir.", "Alors une chose à la fois. Note ce que tu ne comprends pas."],
  "galois": ["Y a-t-il quelque chose que tu veux faire et pour quoi tu n'as jamais eu le temps ?", "Oui, et je veux commencer maintenant.", "Oui, mais ce n'est pas le moment.", "N'attends pas. Je le pense vraiment : n'attends pas."],
  "da_vinci": ["As-tu déjà observé comment un oiseau se pose ?", "Non, apprends-moi à regarder.", "Oui : d'abord les ailes, puis les serres.", "Exactement ! Les meilleurs maîtres sont ceux qui ne disent rien."],
  "hippocrates": ["Dis-moi, où te sens-tu le plus mal aujourd'hui ? Ne pense pas aux causes, seulement à ce que tu ressens.", "Un peu fatigué, les épaules lourdes.", "Rien, je vais bien.", "Mm. Le corps parle d'abord ; nous écouterons lentement."],
  "su_shi": ["Les poèmes peuvent attendre, pas le dîner. Que voudrais-tu manger ?", "Un bol de soupe de nouilles chaude.", "Choisis, je mange n'importe quoi.", "Bien ! Je trouverai le moyen que ce soit meilleur que ça n'en a l'air."],
  "li_bai": ["La lune est belle ce soir. Dis-moi, devrions-nous prendre une tasse de thé ?", "Oui, je m'assois un moment avec toi.", "Bois-la, j'ai encore à faire.", "La lune n'attend personne, mais elle ne presse personne non plus. Reste un moment."],
  "du_fu": ["Je pense souvent combien ce serait bien si chacun avait une maison chaude. Qu'en penses-tu ?", "En voici une. Es-tu bien maintenant ?", "C'est trop difficile ; s'occuper d'une famille suffit.", "Réchauffer un foyer, c'est réchauffer un coin du monde."],
  "ada": ["Penses-tu qu'une machine pourrait un jour comprendre la poésie ?", "Peut-être, si quelqu'un le lui apprenait.", "Non, la poésie est l'affaire des humains.", "Belle question. Ne tirons pas de conclusions hâtives ; usons d'abord pleinement de l'imagination."],
  "pasteur": ["Tout ce qu'on ne voit pas n'est pas absent, tu sais. T'es-tu lavé les mains ?", "Oui, ne t'inquiète pas.", "J'y vais tout de suite.", "Bien. Le hasard favorise ceux qui sont préparés, et la santé aussi."],
  "med.0": ["As-tu bu de l'eau aujourd'hui, et mangé ? Prends d'abord soin de toi, puis des autres.", "Oui, les deux.", "Pas encore, j'y vais.", "Bien. C'est le remède le moins cher."],
  "med.1": ["Comment dors-tu ? Le sommeil est la plus ancienne des ordonnances.", "Plutôt bien.", "Pas bien, je me réveille souvent.", "Note-le ; cette nuit nous chercherons ensemble."],
  "sci.0": ["Une chose m'intrigue : pourquoi les adultes s'attendrissent-ils dès qu'un enfant pleure ?", "Parce que nous ne supportons pas sa tristesse.", "L'évolution, sans doute.", "Intéressant. Les deux explications méritent une expérience."],
  "sci.1": ["As-tu remarqué que les ombres sont un peu plus courtes aujourd'hui qu'hier ?", "Maintenant que tu le dis, oui.", "Je n'avais pas remarqué.", "Le monde change sans cesse ; nous sommes seulement trop occupés pour regarder."],
  "art.0": ["Une devinette : un mot pour ton humeur d'aujourd'hui.", "Calme.", "Agitée.", "Un bon mot. Je le garde ; il finira peut-être dans un poème."],
  "art.1": ["La lumière de ta maison est ravissante. As-tu déjà passé un crépuscule à ne rien faire, juste à regarder ?", "Parfois.", "Non, je suis toujours occupé.", "Essaie. Les plus beaux tableaux et poèmes naissent souvent de l'oisiveté."],
  "edu.0": ["Qu'as-tu lu récemment ? Pas forcément un livre ; tout compte.", "Un album illustré pour enfants.", "Rien du tout.", "Les albums illustrés comptent, et ils sont parmi les plus soigneusement écrits."],
  "edu.1": ["Laisse-moi te demander : enseigner, est-ce pour qu'on retienne ou pour qu'on questionne ?", "Pour qu'on questionne.", "Pour qu'on retienne.", "Les deux réponses sont justes ; seul l'ordre diffère."],
  "pol.0": ["Un foyer ressemble à un petit royaume : l'un cuisine, l'autre balaie, un autre maintient la paix. Qui es-tu ?", "Un peu de tout.", "Je maintiens la paix.", "Alors tu occupes le poste le plus difficile."],
  "pol.1": ["Voir l'ensemble d'abord, puis les détails. Quel est l'ensemble de ta maison aujourd'hui ?", "Que tout le monde est en sécurité.", "Je n'y ai pas pensé.", "La sécurité suffit. Beaucoup poursuivent ce mot toute leur vie."],
  "trv.0": ["Loin de chez moi, ce n'est pas le paysage qui me manque, mais un bol de nourriture chaude. Et toi ?", "Pareil.", "Le calme me manque.", "Chacun a sa propre nostalgie. Les deux valent la peine d'être gardées."],
  "trv.1": ["As-tu déjà pensé que cette maison est le plus long chemin que tu aies parcouru ?", "Non, mais cela semble juste.", "Oui, je le parcours chaque jour.", "Tout à fait. Les plus longs voyages ne passent souvent pas la porte."]
});
CY.i18n.register("fr", { "shop.sec_home": "Pour la maison", "shop.sec_gifts": "Cadeaux pour les visiteurs", "shop.gift_note": "Un cadeau ne compte que s'il correspond à ce dont le visiteur a vraiment besoin. Trois de chaque au maximum. Pour l'offrir, maintiens « Offrir un cadeau » dans le cercle du visiteur.", "gift.empty": "Le sac est vide. Touche le compteur d'argent et passe à la section cadeaux de la boutique." });
CY.i18n.register("fr", { "start.lead_title": "Qui es-tu ?", "start.lead_note": "Choisis un membre de la famille et tu es cette personne. Tu peux le changer à tout moment : touche 👥 en haut à droite et choisis « {btn} » à côté d'une personne.", "start.next": "Continuer", "start.house_title": "La vieille maison", "start.house_p1": "Tu es revenu dans la vieille maison. Les personnes dont tu veux prendre soin y vivent, et tu travailles et veilles sur elles sous le même toit.", "start.house_p2": "Le portail de la cour fait un petit clic et {name} entre, une lampe à huile à la main.", "start.house_say": "« Quel endroit intéressant. Je n'emprunte un lit que pour un moment, et je partirai bientôt. »", "start.house_p3": "Désormais, d'autres personnes franchiront ce portail et resteront un jour ou deux." });

CY.i18n.cards("fr", {
  arrive: "{n} franchit la porte d'entrée et demanda à rester quelques jours.",
  ok: "Avant de partir, {n} laissa un souvenir : {s}. Et dit : « {q} »",
  miss: "{n} remercia et repassa la porte."
}, {
  sun_simiao: ["Sun Simiao", "Dynastie Tang, Chine", "Une copie d'une page d'ordonnances", "Un remède n'a pas besoin d'être cher, seulement adapté à la maladie.", "Il disait qu'un guérisseur ne doit pas distinguer le riche du pauvre ; quiconque vient est un malade, et tous sont traités de même.", "Il aimait cueillir des herbes dans les collines et disait que les meilleurs remèdes poussent souvent là où personne ne regarde.", "Il soupesa les graines dans sa paume et dit que cette poignée pouvait aider beaucoup de monde."],
  heo_jun: ["Heo Jun", "XVIe et XVIIe siècles, Corée de Joseon", "Une copie d'une page de dessins d'herbes", "Un livre de médecine que les gens ordinaires peuvent lire est un bon livre.", "Il disait que les plantes médicinales devaient être reconnaissables par tous, et donna donc à chacune son nom local.", "Il disait que prévenir vaut mieux que guérir et que prendre soin du corps chaque jour est le meilleur remède.", "Il posa la couverture sur ses genoux et hocha la tête ; maintenant il faisait chaud."],
  hanaoka: ["Hanaoka Seishu", "Période d'Edo, Japon", "Une copie d'une page de notes de formules", "Épargner la douleur à une personne est la première bonté d'un guérisseur.", "Il disait avoir passé de longues années à préparer un breuvage qui fait dormir le malade, et ne l'employer qu'une fois sûr de son innocuité.", "Il disait qu'avant que les mains ne commencent, le malade doit d'abord cesser d'avoir peur.", "Il les enfila et dit que lorsque les doigts sont chauds, l'esprit est calme."],
  charaka: ["Charaka", "Inde antique, auteur traditionnel de la Charaka Samhita", "Une copie d'une page de notes de consultation", "Une question de plus vaut plus qu'une ordonnance de plus.", "Il disait qu'un médecin doit demander encore et encore : qu'as-tu mangé, comment as-tu dormi, qu'as-tu en tête ?", "Il disait qu'un bon médecin reste auprès du malade comme un ami.", "Il tenait la soupe chaude et dit qu'il faut d'abord se réchauffer avant de parler."],
  razi: ["Al-Razi", "IXe et Xe siècles, Perse et Bagdad", "Une copie d'une page de dossiers de cas", "Regarder souvent, noter avec soin, et seulement alors parler.", "Il disait noter le cas de chaque malade, et qu'un cas vaut plus qu'un livre.", "Il disait qu'au chevet on se fie à sa propre observation, pas seulement aux vieux livres.", "Il se pencha tout près et ne dit rien pendant un long moment."],
  zahrawi: ["Al-Zahrawi", "Xe et XIe siècles, Al-Andalus", "Une copie d'une page de dessins d'instruments", "Un métier doit être dessiné de génération en génération, sinon il se perd.", "Il dessinait chaque instrument chirurgical qu'il employait et disait qu'une image vaut mille mots.", "Il disait que les mains d'un chirurgien doivent être sûres, son esprit minutieux et ses outils propres.", "Il le posa sur la table, jeta un œil à l'horloge et dit que la ponctualité compte avant tout."],
  galen: ["Galien", "IIe siècle, Pergame et Rome", "Une copie d'une page de notes d'observation", "Regarde beaucoup, pense beaucoup, puis conclus.", "Il disait qu'un médecin doit aussi être philosophe : d'abord apprendre à observer, ensuite à penser.", "Il disait qu'un bon médecin n'a le droit de parler de maladie qu'après avoir senti le pouls de sa propre main.", "Il drapa l'écharpe sur ses épaules et ouvrit le livre."],
  vesalius: ["André Vésale", "XVIe siècle, Flandre", "Une copie d'une page d'une planche anatomique", "Fie-toi à tes yeux et aux lignes que tu traces.", "Il disait que ce que montraient les livres ne correspondait pas à ce qu'il voyait, et vérifiait donc tout de ses propres yeux.", "Il disait que pour comprendre le corps, il faut dessiner sa structure, partie après partie.", "Il mélangea une couleur et dit que ce trait devait être très exact."],
  jenner: ["Edward Jenner", "XVIIIe et XIXe siècles, Royaume-Uni", "Un croquis d'une vache", "D'abord observer, ensuite réfléchir, et seulement à la fin agir.", "Il disait avoir remarqué que les trayeuses attrapaient rarement la variole, et que cela méritait réflexion.", "Il disait que les bonnes réponses se cachent souvent dans l'observation de tous les jours.", "Il enfila les chaussures et dit qu'il irait marcher à la campagne pour regarder les vaches."],
  blackwell: ["Elizabeth Blackwell", "XIXe siècle, Royaume-Uni et États-Unis", "Une copie d'une lettre d'admission", "Une fois la porte ouverte, ceux qui suivent peuvent passer.", "Elle disait que de nombreuses écoles l'avaient refusée, jusqu'à ce qu'une finisse par l'accepter.", "Elle disait que les femmes peuvent faire de bonnes médecins, si seulement on leur donne leur chance.", "Elle enfila le manteau, ses yeux s'éclairèrent, et elle dit qu'elle lirait tard cette nuit."],
  chagas: ["Carlos Chagas", "XIXe et XXe siècles, Brésil", "Une page de croquis vus au microscope", "La maladie naît de la vie quotidienne, alors cherche-la là.", "Il disait que dans un petit village, il avait relié un minuscule insecte à une maladie.", "Il disait que pour comprendre une maladie, il faut comprendre à la fois l'insecte, les gens et les maisons.", "Il ouvrit le parapluie contre le soleil et se pencha longtemps sur la lentille."]
});
CY.i18n.said("fr", { sun_simiao: ["Une vie humaine vaut plus que mille pièces d'or ; une ordonnance qui aide une personne fait plus de bien que l'or."], galen: ["Le meilleur médecin est aussi un philosophe."] });
CY.i18n.register("fr", { "shop.sec_bed": "Lits", "shop.bed_note": "Les lits décident du nombre de personnes qui peuvent vivre à la maison. La famille et les visiteurs en occupent un chacun. Ils sont chers, alors économise doucement. Les bébés dorment dans un berceau et ne prennent pas de lit.", "shop.bed_slot": "Ajouter un lit", "shop.bed_slot_fx": "Un lit de plus permet à une personne de plus de vivre ici et à un visiteur de plus de rester. Quand les lits sont épuisés, on ne peut plus ajouter personne et aucun nouveau visiteur ne viendra.", "shop.beds_now": "Lits {n}/{m}, {u} occupés", "shop.full": "Tous les lits achetés", "shop.sec_daily": "Objets du quotidien", "shop.sec_decor": "Décoration", "shop.decor_note": "La décoration est purement esthétique et n'a aucun effet sur aucune valeur.", "shop.cabinet_fx": "Se place dans le salon et garde les souvenirs que laissent les visiteurs. Passe la souris sur un souvenir pour voir qui l'a laissé. Purement esthétique, sans effet sur aucune valeur.", "shop.decor1_fx": "Une petite plante dans le salon. Purement esthétique, sans effet sur aucune valeur.", "shop.decor2_fx": "Un tapis et un lampadaire dans le salon. Purement esthétique, sans effet sur aucune valeur.", "shop.decor3_fx": "Une radio et une plante dans le salon. Purement esthétique, sans effet sur aucune valeur.", "shop.gift_note": "Tous les cadeaux ne plaisent pas au visiteur : un cadeau qu'il adore ajoute beaucoup d'affection, un cadeau ordinaire en ajoute peu. Quand l'affection suffit, le visiteur laisse un présent en retour. Trois de chaque au maximum. Pour l'offrir, maintiens « Offrir un cadeau » dans le cercle du visiteur.", "add.no_bed": "Il n'y a plus de lit libre. Achète un lit à la boutique avant d'ajouter quelqu'un.", "gift.fav": "Affection {n}/{m}", "gift.fav_ok": "Atteint, un présent sera laissé en retour", "gift.mild": "{name} l'a accepté et t'a remercié, mais ne semblait pas particulièrement content.", "field.med": "Médecine", "field.sci": "Science et ingénierie", "field.art": "Littérature et art", "field.edu": "Savoir et éducation", "field.pol": "Politique et armée", "field.trv": "Voyage et navigation" });
