CY.i18n.register("fr", {"loc.kids": "Chambre des enfants", "shop.bed_slot": "Ajouter un lit d’amis", "shop.bed_note": "La maison a trois chambres de deux lits : pour le couple, pour les enfants et pour les aînés. Ces lits de famille sont gratuits, la famille compte six personnes au plus. La chambre d’amis commence avec un lit pour les voyageurs du temps, jusqu’à trois, et tu peux acheter les deux autres. Les bébés dorment dans un berceau et ne prennent pas de lit.", "shop.bed_slot_fx": "Un lit d’amis de plus, un voyageur de plus.", "shop.beds_now": "Lits d’amis {n}/{m}, occupés {u}", "add.no_bed": "Les six lits de la famille sont pris, personne d’autre ne peut s’installer."});
